local KTool = CS.Engine.Lib.KTool
local Singleton = import('Frame.Singleton')

---@class ActivityCrisisMgr
local ActivityCrisisMgr = Class('ActivityCrisisMgr',Singleton)
local ActivityCrisisDojo = import("Game.Dojo.ActivityCrisisDojo")
function ActivityCrisisMgr:__init()
    self:CleanCache()
    self.newCompletedTask = 0
    self.completeQuestId = 0
    self.preQuestData = {}
end

function ActivityCrisisMgr:CleanCache()
    self.activityCrisisDojo = nil
    self.newCompletedTask = nil
    self.completeQuestId = nil
    self.preQuestData = nil
end

function ActivityCrisisMgr:SetPreQuestData(questId,selectGroupCirLine ,selectData)
    if self.preQuestData then
        self.preQuestData.questId = nil
        self.preQuestData.selectGroupCirLine = nil
        self.preQuestData.selectData = nil
    end
    self.preQuestData = {
        questId  = questId , 
        selectData  = selectData , 
        selectGroupCirLine = selectGroupCirLine 
    }
end
function ActivityCrisisMgr:GetPreQuestData()
    return self.preQuestData
end

function ActivityCrisisMgr:__delete()
    self:CleanCache()
end

function ActivityCrisisMgr:InitialDojo(data)
    if isNull(self.activityCrisisDojo) then
        self.activityCrisisDojo = ActivityCrisisDojo.New()
    end
    self.activityCrisisDojo:Fill(data)
end

function ActivityCrisisMgr:GetActivityDojo()
    return self.activityCrisisDojo
end

function ActivityCrisisMgr:IsFinishCrisisQuest(questId,taskId)
    local receiveIds = self.activityCrisisDojo:GetCompletedTaskIds()
    for k, v in pairs(receiveIds) do
        if checkNumber(v) == checkNumber(taskId) then
            return true
        end
    end
    return false
end

function ActivityCrisisMgr:UpdateReceiveIds(taskId)
    local taskData = self.activityCrisisDojo:GetReceivedTaskIds()
    table.insert(taskData,taskId)
end

function ActivityCrisisMgr:SaveActivityData(data)
    self.activityData = data
end

function ActivityCrisisMgr:GetActivityData()
    return self.activityData
end

function ActivityCrisisMgr:SaveEntryData(data)
    self.entryData = data
end

function ActivityCrisisMgr:GetEntryData()
    return self.entryData
end

function ActivityCrisisMgr:BattleEndUpdate(battleData)
    self:UpdateNewCompleteTask(battleData.newCompletedTask)
    if checkNumber(battleData.newCompletedTask) > 0 then
        self:UpdateCompleteQuestId(battleData.questId)
    end
end

function ActivityCrisisMgr:UpdateNewCompleteTask(value)
    self.newCompletedTask = value
end

function ActivityCrisisMgr:UpdateCompleteQuestId(questId)
    self.completeQuestId = questId
end

function ActivityCrisisMgr:GetCompleteQuestId()
    return self.completeQuestId
end

function ActivityCrisisMgr:IsNeedOpenTaskDialog()
    return checkNumber(self.newCompletedTask) > 0
end

function ActivityCrisisMgr:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCrisisMgr